import { CommonPoolController } from "approot/global/controllers/common.pool.controller";
import { RegistryBasedComponentTemplate } from "approot/global/components/registry/registry.model";

class SchoolPoolController extends CommonPoolController {
	initTitle() {
		this.$scope.$parent.page = {
			title: this.language.FilterUsers.kFreeStudentsList
		};
	}
}

export const PoolComponent = {
	controller: SchoolPoolController,
	controllerAs: "ctrl",
	template: RegistryBasedComponentTemplate
}


