import { RegistryBasedComponentTemplate, RegistryInfo } from "approot/global/components/registry/registry.model";

class EServicesStudentListController {
	public registryInfo: RegistryInfo;

	/*@ngInject*/
	constructor($scope: any) {

		$scope.$parent.page = {
			title: "Список распределённых"
		};

		this.registryInfo = {
			url: "/webapi/movement/list/eservices/registry",
			filtersUrl: "/webapi/movement/list/eservices/registry/filter",
			buttons: [],
			linkButtons: []
		};
	}
}

export const EServicesStudentListComponent = {
	controller: EServicesStudentListController,
	controllerAs: "ctrl",
	template: RegistryBasedComponentTemplate
}


