import { EnumItemDto, NamedEntityDto } from "../models/common.model";
import { RegistryInfo, PreserveWhiteSpaceDecorator, LinkFieldDecorator, IRegistryController, RegistryBtn } from "../components/registry/registry.model";
import { LongWorkService, DialogsService } from "../providers/uikit.dialogs";
import { UnderscoreStatic } from "underscore";
import { EditPoolUserComponent } from "./pool.edituser.component";

declare var _: UnderscoreStatic;

export abstract class CommonPoolController {
	public registryInfo: RegistryInfo;
	public controller: IRegistryController;

	/*@ngInject*/
	constructor(
		protected $scope,
		protected $q: ng.IQService,
		private $longWork: LongWorkService,
		protected $http: ng.IHttpService,
		protected $uibModal: ng.ui.bootstrap.IModalService,
		protected language: any
	) {
		let preserveWhiteSpaceDecorator = new PreserveWhiteSpaceDecorator();

		this.initTitle();

		this.registryInfo = {
			url: "/webapi/movement/pool/registry",
			filtersUrl: "/webapi/movement/pool/registry/filter",
			fieldDecorators: {
				"studentFio": new LinkFieldDecorator((row) => this.editUser(row)),
				"identityDocumentInfo": preserveWhiteSpaceDecorator,
				"parentsInfo": preserveWhiteSpaceDecorator,
				"addressInfo": preserveWhiteSpaceDecorator
			},
			buttons: this.getButtons(),
			linkButtons: []
		};
	}

	protected abstract initTitle();

	protected getButtons(): RegistryBtn[] {
		return [];
	}

	protected userPoolInfo: any;
	protected schoolSettings: any;

	protected departOrgs: NamedEntityDto[];
	protected departReasons: any[] = [];

	protected inaccessibilityReasons: any[];
	protected availabilityTypes: any[];
	protected outsideTypes: any[];
	protected poolCategories: any[];

	editUser(user) {
		var processing = this.$longWork.show();

		var idParts = user.id.split("_");
		let params = {
			studentId: idParts[1],
			docId: null
		};
		if (parseInt(idParts[0]) > 0) {
			params.docId = idParts[0];
		}

		const queries = [
			this.$http.get(`/webapi/movement/pool/student`, { params })
				.then((response) => {
					this.userPoolInfo = response.data;
					this.departOrgs = [{ id: null, name: "Не указано" }];
					if (this.userPoolInfo.departOrg && this.userPoolInfo.departOrg.id) {
						this.departOrgs = this.departOrgs.concat([{ id: this.userPoolInfo.departOrg.id, name: this.userPoolInfo.name }]);
					}
					if (this.userPoolInfo.poolOrganizationSchoolYearId) {
						return this.$http.get(`/webapi/school/settings`, { params: { yearId: this.userPoolInfo.poolOrganizationSchoolYearId } });
					}
					return Promise.resolve(null);
				})
				.then((response) => {
					this.schoolSettings = response && response.data;
				}),
			this.$http.get(`/webapi/movement/pool/inaccessibilityReasons`)
				.then((response: ng.IHttpResponse<any[]>) => {
					this.inaccessibilityReasons = response.data;
				}),
			this.$http.get(`/webapi/movement/pool/availabilityTypes`)
				.then((response: ng.IHttpResponse<EnumItemDto[]>) => {
					this.availabilityTypes = _.filter(response.data, (t) => t.key !== "Enrolled");
				}),
			this.$http.get(`/webapi/movement/pool/outsideTypes`)
				.then((response: ng.IHttpResponse<any[]>) => {
					this.outsideTypes = response.data;
				}),
			this.$http.get(`/webapi/movement/pool/categories`)
				.then((response: ng.IHttpResponse<any[]>) => {
					this.poolCategories = response.data;
				})
		];

		let modalInstanceData = {
			templateUrl: EditPoolUserComponent.templateUrl,
			controller: EditPoolUserComponent.controller,
			controllerAs: EditPoolUserComponent.controllerAs,
			title: 'Информация',
			resolve: {
				userPoolInfo: () => this.userPoolInfo,
				departOrgs: () => this.departOrgs,
				departReasons: () => this.departReasons,
				availabilityTypes: () => this.availabilityTypes,
				inaccessibilityReasons: () => this.inaccessibilityReasons,
				outsideTypes: () => this.outsideTypes,
				poolCategories: () => this.poolCategories,
				schoolSettings: () => this.schoolSettings
			}
		};

		this.$q.all(queries)
			.then(() => {
				processing.close();
				this.$uibModal.open(modalInstanceData).result
					.then(() => {
						this.controller.load();
					});
			}, () => processing.close());

	}
}



