"use strict";

import { BaseRepository } from "approot/global/repository/baseRepository";
import { DialogsService, LongWorkService } from "approot/global/providers/uikit.dialogs";
import { AppContext } from "approot/global/services/context";
import { EducationGroupData, MoveDocDetailsDto, MoveDocDto, MoveStudentInfo, MoveDocSubTypeEnumItem, MoveDocSaveModel, MoveDocType, DepartReasonDto, MovePeriodDto } from "./movement.model";
import { EnqueueInfo } from "approot/global/services/queue/taskqueue.model";
import { EnumItemDto } from "approot/global/models/common.model";

export class MoveSourceRepository extends BaseRepository {
	getMovementSources(docType, docSubType) {
		const params = { docType, docSubType };

		return this.$http.get("/webapi/movement/sources", { params })
			.then(this.handleResponse, this.handleError);
	}

	getMovementSourceInfo(sourceId) {
		return this.$http.get(`/webapi/movement/sources/${sourceId}`)
			.then(this.handleResponse, this.handleError);
	}

	getList(sourceId, data) {
		return this.$http.post(`/webapi/movement/sources/${sourceId}/getList`, data)
			.then(this.handleResponse, this.handleError);
	}

	loadDataForMoveDocPrint() {
		return this.$http.get(`/webapi/movement/sources/getDataPrint`)
			.then(this.handleResponse, this.handleError);
	}
}

export class MoveClassesRepository extends BaseRepository {
	/*@ngInject*/
	constructor($http, $dialogs: DialogsService, $longWork: LongWorkService, private appContext: AppContext) {
		super($http, $dialogs, $longWork)
	}

	getEducGroupsFrom(docType, docSubType): Promise<EducationGroupData[]> {
		const yearId = this.appContext.yearId;
		const params = { yearId, docType, docSubType };

		return this.$http.get(`/webapi/movement/educGroups/from`, { params })
			.then(this.handleResponse, this.handleError);
	}

	getEducGroupsTo(docType, docSubType, fromClassId): Promise<EducationGroupData[]> {
		const yearId = this.appContext.yearId;
		const params = { yearId, docType, docSubType, fromClassId: null };
		if (fromClassId) {
			params.fromClassId = fromClassId;
		}
		return this.$http.get("/webapi/movement/educGroups/to", { params })
			.then(this.handleResponse, this.handleError);
	}

	getPoolCategories() {
		return this.$http.get("/webapi/movement/pool/categories")
			.then(this.handleResponse, this.handleError);
	}

}

export class MoveDocRepository extends BaseRepository {
	/*@ngInject*/
	constructor($http, $dialogs: DialogsService, $longWork: LongWorkService, private appContext: AppContext) {
		super($http, $dialogs, $longWork)
	}

	getAll(docType: number, docSubType: number, classId?: number, grade?: number, detailed?: boolean): Promise<MoveDocDetailsDto[] | MoveDocDto[]> {
		let params = { docType: null, docSubType: null, classId: null, grade: null, detailed };
		if (docType > 0) {
			params.docType = docType;
		}
		if (docSubType >= 0) {
			params.docSubType = docSubType;
		}
		if (grade >= 0) {
			params.grade = grade;
		}
		if (classId > 0) {
			params.classId = classId;
		}

		return this.$http.get("/webapi/movement/documents", { params })
			.then(this.handleResponse, this.handleError);
	}

	getDoc(docId: number, detailed?: boolean): Promise<MoveDocDetailsDto | MoveDocDto> {
		return this.$http.get(`/webapi/movement/documents/${docId}`, { params: { detailed } })
			.then(this.handleResponse, this.handleError);
	}

	getShowAwardFlag(subDocId) {
		return this.$http.get(`/webapi/movement/documents/showAwardFlag/${subDocId}`)
			.then(this.handleResponse, this.handleError);
	}

	getSchoolSettings() {
		return this.$http.get(`/webapi/school/settings`, { params: { yearId: this.appContext.yearId } })
			.then(this.handleResponse, this.handleError);
	}

	getEditReferencesFlag() : Promise<boolean> {
		return this.$http.get("/webapi/appflags/editReferences")
			.then(this.handleResponse, this.handleError);
	}

	getState(docType) {
		let params = { moveDocType: null };
		if (docType) {
			params.moveDocType = docType;
		}
		return this.$http.get("/webapi/movement/documents/state", { params: params })
			.then((response) => response.data, this.handleError);
	}

	updateMoveDoc(moveDoc: MoveDocSaveModel, studentsData) : Promise<void> {
		const data = {
			moveDoc: moveDoc,
			studentData: studentsData
		};

		this.$longWork.show();

		return this.$http.post(`/webapi/movement/documents/${moveDoc.id}`, data)
			.then(this.longWorkResponseHandler, this.handleError);
	}

	getAllOutSideTypes() : Promise<EnumItemDto[]> {
		return this.$http.get(`/webapi/movement/pool/outsideTypes`)
			.then(this.handleResponse, this.handleError);
	}

	getDepartReasons(moveType: MoveDocType, funcType: number, outSideType?: number, eoType? : number) : Promise<DepartReasonDto[]> {
		return this.$http.get(`/webapi/movement/departReasons`, { params: { moveType: moveType, funcType: funcType, outsideType: outSideType, eoType: eoType } })
			.then(this.handleResponse, this.handleError);
	}

	getAwardTypes(subDocId: number) {
		return this.$http.get(`/webapi/movement/awardTypes`, { params: { subDocId: subDocId } })
			.then(this.handleResponse, this.handleError);
	}

	removeStudentsFromDoc(docId: number, students: MoveStudentInfo[], queue?: boolean): Promise<number | EnqueueInfo> {
		let docStudentId = students.map(s => s.docStudentId);

		const params = {
			docStudentId: docStudentId,
			queue: null

		}

		if (queue) {
			params.queue = queue;
		}

		this.$longWork.show();

		return this.$http.delete(`/webapi/movement/documents/${docId}/students`, { params: params })
			.then(this.longWorkResponseHandler, this.handleError);
	}

	del(docId: number, queue?: boolean): Promise<void | EnqueueInfo> {
		if (queue) {
			return this.$http.delete(`/webapi/movement/documents/${docId}`, { params: { queue: true } })
				.then(this.handleResponse, this.handleError);
		}

		this.$longWork.show();

		return this.$http.delete(`/webapi/movement/documents/${docId}`)
			.then(this.longWorkResponseHandler, this.handleError);
	}

	getMoveDocTypes() : Promise<EnumItemDto[]> {
		return this.$http.get("/webapi/references/movedoctype", { params: { "at": this.appContext.at } })
			.then(this.handleResponse, this.handleError);
	}

	getMoveDocSubTypes() : Promise<MoveDocSubTypeEnumItem[]> {
		return this.$http.get("/webapi/references/movedocsubtype", { params: { "at": this.appContext.at } })
			.then(this.handleResponse, this.handleError);
	}

	getYears() {
		return this.$http.get("/webapi/context/years")
			.then(this.handleResponse, this.handleError);
	}

	getMovePeriods(globalYearId) : Promise<MovePeriodDto[]> {
		return this.$http.get("/webapi/movement/movePeriods", { params: { globalYearId: globalYearId } })
			.then(this.handleResponse, this.handleError);
	}

	private get longWorkResponseHandler(){
		return this.handleLongWorkResponse.bind(this);
	}
	
	private handleLongWorkResponse(response) {
		this.$longWork.close();
		return response.data;
	}
}


