declare var angular: ng.IAngularStatic;
declare var dateUtils: any;

const module = angular.module("irtech.netcity.school.movement",
	[
		"ngRoute", "ngSanitize", "ngMessages", "ui.select", "uikit.alerts", "uikit.dialogs", "ui.bootstrap", "ngFileUpload", "ui.tree",
		"irtech.netcity.common", "irtech.netcity.ui-components"
	]);

import { PoolComponent } from "./pool/pool.component";
import { EServicesStudentListComponent } from "./eservicesPool/eservices.studentlist.component";
import { MoveDocRepository, MoveSourceRepository, MoveClassesRepository } from "./movement.repository";

/*@ngInject*/
let config = ($routeProvider, $locationProvider: ng.ILocationProvider) => {
	$routeProvider
		.when("/pool/", PoolComponent)
		.when("/eservices", EServicesStudentListComponent)
		.otherwise(PoolComponent);
	$locationProvider.hashPrefix("");
	$locationProvider.html5Mode({
		enabled: true,
		requireBase: true
	});
}

module
	.service("moveDocRepository", MoveDocRepository)
 	.service("moveSourceRepository", MoveSourceRepository)
 	.service("moveClassesRepository", MoveClassesRepository)
	.directive("nsDateModel", () => {
		const toStr = function (dateParam) {
			return dateParam ? dateUtils.date2strfrm(new Date(dateParam), `dd${String.fromCharCode(1)}mm${String.fromCharCode(1)}yyyy${String.fromCharCode(1)}.`) : null;
		}
		return {
			restrict: "A",
			scope: {
				date: "=nsDateModel"
			},
			link: (scope: any, element: any) => {
				let isoDate = scope.date;
				let strDate = toStr(isoDate);

				$(element).val(strDate);

				$(element).change(() => {
					let date = dateUtils.str2date($(element).val());
					if (date) {
						scope.date = date.toISOString();
					} else {
						scope.date = null;
						element.$invalid = true;
					}
					scope.$apply();
				});
			},
			replace: false
		}
	})
	.config(config);


