import { NetCityModalController } from "./netcityModalCtrl";
import SearchSource from "../searchSource";
import { DialogsService } from "../providers/uikit.dialogs";
import { ChangeTracker } from "../changeTracker";
import { AlertsService } from "../providers/uikit.alerts";
import { UnderscoreStatic } from "underscore";

declare var _ : UnderscoreStatic;

class EditPoolUserController extends NetCityModalController {
	public searchCtx: SearchSource;
	public selection: any;
	public departReasons: any[]
	public outsideTypesAll: any[];

	/*@ngInject*/
	constructor(
		$scope : ng.IScope,
		$dialogs: DialogsService,
		$uibModalInstance: ng.ui.bootstrap.IModalInstanceService,
		changeTracker: ChangeTracker,

		private $http,
		public language,
		private $alerts: AlertsService,

		public userPoolInfo,
		public departOrgs,
		public inaccessibilityReasons,
		public availabilityTypes,
		public outsideTypes,
		public poolCategories,
		public schoolSettings
		) {

		super($scope, $uibModalInstance, changeTracker, $dialogs);

		this.outsideTypesAll = outsideTypes;

		this.searchCtx = new SearchSource({
			departOrgs: {
				url: "/webapi/movement/departorgs",
				searchParam: "name",
				params: {
					moveType: this.userPoolInfo.moveType,
					funcType: this.userPoolInfo.poolOrganizationFuncType,
					schoolId: this.userPoolInfo.poolOrganization == null ? null : this.userPoolInfo.poolOrganization.id,
					step: this.userPoolInfo.moveType === "Graduate" && this.userPoolInfo.poolOrganizationFuncType === "School" && this.schoolSettings ? this.getStepByGrade(this.userPoolInfo.poolOrganizationClassGrade) : -1
				},
				minChars: 1,
				emptyChoiceItem: { id: null, name: "Не указано" }
			}
		}, $http);

		this.selection = {
			id: userPoolInfo.departOrg ? userPoolInfo.departOrg.id : null,
			name: userPoolInfo.departOrg ? userPoolInfo.departOrg.name : null,
			outSideType: userPoolInfo.departOrgOutsideType,
			type: userPoolInfo.departEoType
		};

		this.onFilterChange(this.selection);
	}

	save(current) {
		this.$http.post(`/webapi/movement/pool/student`, current).then(detailInfo => {
			this.$alerts.success("Данные сохранены");
			this.$uibModalInstance.close(detailInfo.data);
		}, (response) => {
			const data = response.data;
			this.$alerts.error(data && data.message, data && data.details);
		});
	}

	getStepByGrade(grade : number) {
		if (grade >= this.schoolSettings.juniorStepGrade.start && grade <= this.schoolSettings.juniorStepGrade.end) {
			return 1;
		} else if (grade >= this.schoolSettings.middleStepGrade.start && grade <= this.schoolSettings.middleStepGrade.end) {
			return 2;
		} else if (grade >= this.schoolSettings.seniorStepGrade.start && grade <= this.schoolSettings.seniorStepGrade.end) {
			return 3;
		};
		return -1;
	}

	onFilterChange(departOrg) {
		const outsideType = departOrg && departOrg.id ? departOrg.outSideType : this.userPoolInfo.departOrgOutsideType;
		this.userPoolInfo.departOrgOutsideType = outsideType;
		if (departOrg && departOrg.id) {
			this.outsideTypes = _.filter(this.outsideTypesAll, (item) => item.key === this.userPoolInfo.departOrgOutsideType);
		}
		else {
			this.outsideTypes = _.toArray(_.map(this.outsideTypesAll, (item) => item));
		}
		const eoType = (departOrg && departOrg.type) ? departOrg.type : this.userPoolInfo.departEoType;
		this.userPoolInfo.departOrg = _.clone(departOrg);

		this.$http.get(`/webapi/movement/departReasons`, { params: { moveType: this.userPoolInfo.moveType, funcType: this.userPoolInfo.poolOrganizationFuncType, eoType: eoType } }).then((result) => {
			this.departReasons = result.data;
			if (this.userPoolInfo.departReason && this.userPoolInfo.departReason.id && this.departReasons && this.departReasons.length && !_.find(this.departReasons, (item) => item.id === this.userPoolInfo.departReason.id)) {
				this.userPoolInfo.departReason = _.clone(this.departReasons[0]);
			}
			this.$scope.$applyAsync();
		});
	}

	initInaccessibilityReason(userPoolInfo) {
		if (!userPoolInfo.availabilityInfo.inaccessibilityReason) {
			userPoolInfo.availabilityInfo.inaccessibilityReason = userPoolInfo.availabilityInfo.inaccessibilityReason = this.inaccessibilityReasons[0];
		}
	}
}

export const EditPoolUserComponent = {
	controller : EditPoolUserController,
	controllerAs: "$ctrl",
	templateUrl : '/static/dist/app/global/controllers/pool.edituser.component.html'
}



